pub async fn verify(pool: &PgPool, start: u64, head: u64) -> Result<Vec<(u64, u64)>, sqlx::Error> {
    // 原来是 .unwrap()：兜底的 verifier 自己 panic 掉，反而最没人知道。
    let rows = sqlx::query_as::<_, (i64, i64, i64, i32)>(
        "SELECT from_block, to_block, row_count, attempts FROM ranges_done ORDER BY from_block"
    )
    .fetch_all(pool)
    .await?;

    let mut gaps = Vec::new();
    let mut cursor = start;

    for (f, t, row_count, attempts) in rows {
        let (f, t) = (f as u64, t as u64);
        if f > cursor {
            gaps.push((cursor, f - 1));
        }

        // 标了 done 却一条 log 都没有的 range，重灌一次。
        // attempts 上界很关键：链上真的空的 range 不加这个限制会每天凌晨白跑一遍，
        // 永远收敛不了。灌完还是 0（attempts >= 2）就认了。
        if row_count == 0 && attempts < 2 {
            gaps.push((f, t));
            metrics::counter!("verify_zero_ranges_total").increment(1);
        }

        cursor = cursor.max(t + 1);
    }

    if cursor <= head {
        gaps.push((cursor, head));
    }
    gaps.sort_unstable();
    Ok(gaps)
}
```

调用方加个 `?` 或 `match` 就行（签名从 `Vec<_>` 变成了 `Result<Vec<_>>`）。

两个能自洽的点：现存那 3412 行 `attempts` 走 DEFAULT 1，所以第一次 verify 就会全部被捞起来；而如果重灌又超时，新的 `fetch_logs` 会在重试耗尽后返回 `Err`，`write_range` 根本不会被调用，`attempts` 停在 1 —— 下一晚继续捞。自己会收敛。

