## Patch

### 1. `src/fetch.rs` —— 核心修复

```rust
pub async fn fetch_logs(client: &Client, from: u64, to: u64) -> Result<Vec<RawLog>, FetchError> {
    let body = json!({
        "jsonrpc": "2.0", "id": 1, "method": "eth_getLogs",
        "params": [{ "fromBlock": hex(from), "toBlock": hex(to) }],
    });

    let resp = match client.post(&CFG.rpc_url).json(&body).send().await {
        Ok(resp) => resp,
        Err(e) if e.is_timeout() => {
            // 超时 = 这个 range 我们什么都没拿到，不等于链上没有 log。
            // 必须当失败往上抛，否则调用方拿到空 Vec 会把 range 标成 done。
            warn!(from, to, "request timed out");
            metrics::counter!("rpc_timeouts_total").increment(1);
            metrics::counter!("fetch_errors_total").increment(1);
            return Err(FetchError::Timeout);
        }
        Err(e) => {
            metrics::counter!("fetch_errors_total").increment(1);
            return Err(FetchError::Http(e));
        }
    };

    let v: RpcResponse<Vec<RawLog>> = match resp.json().await {
        Ok(v) => v,
        Err(e) if e.is_timeout() => {
            warn!(from, to, "response body read timed out");
            metrics::counter!("rpc_timeouts_total").increment(1);
            metrics::counter!("fetch_errors_total").increment(1);
            return Err(FetchError::Timeout);
        }
        Err(e) => {
            metrics::counter!("fetch_errors_total").increment(1);
            return Err(FetchError::Http(e));
        }
    };

    if let Some(err) = v.error {
        metrics::counter!("fetch_errors_total").increment(1);
        if err.code == -32005 {
            return Err(FetchError::RateLimited);
        }
        return Err(FetchError::Rpc(err.message));
    }

    match v.result {
        Some(logs) => Ok(logs),
        // 既没 result 也没 error 的响应是坏响应，不是"空 range"。
        // 原来的 unwrap_or_default() 是第二条静默转空的路径。
        None => {
            metrics::counter!("fetch_errors_total").increment(1);
            Err(FetchError::Rpc("response had neither result nor error".into()))
        }
    }
}
```

`FetchError` 加一个变体：

```rust
#[error("request timed out")]
Timeout,
```

### 2. `src/retry.rs`

改完 fetch 之后超时会自动走到现有的重试分支，这里只做三件小事：加 jitter（24 个 worker 退避曲线完全同步会打成脉冲）、给退避封顶、把"重试耗尽"单独计数。**没有改可重试错误的分类**，保持原来"什么错都重试"的语义，减少这次上线的变量。

```rust
pub async fn with_retry<F, Fut, T>(mut f: F) -> Result<T, FetchError>
where
    F: FnMut() -> Fut,
    Fut: Future<Output = Result<T, FetchError>>,
{
    let mut delay = Duration::from_millis(200);
    for attempt in 0..=CFG.max_retries {
        match f().await {
            Ok(v) => return Ok(v),
            Err(e) => {
                if attempt == CFG.max_retries {
                    metrics::counter!("retries_exhausted_total").increment(1);
                    warn!(?e, attempt, "giving up on range");
                    return Err(e);   // 返回真实错因，不再是笼统的 Exhausted
                }
                metrics::counter!("retries_total").increment(1);
                warn!(?e, attempt, "retrying");
                let jitter = Duration::from_millis(rand::random::<u64>() % 250);
                tokio::time::sleep(delay + jitter).await;
                delay = (delay * 2).min(Duration::from_secs(10));
            }
        }
    }
    Err(FetchError::Exhausted)
}
```

注意代价：一个必然超时的 range 现在最坏要烧 6 × 20s ≈ 2 分钟才放弃。如果重灌那一轮吞吐明显掉下来，给超时单独配一个小一点的 `max_retries`（2~3）就够了 —— 超时重试一次通常就过。

### 3. `src/writer.rs` —— 你要的第 1 条

`DO UPDATE` 这条是**必须的**，不然第 2 条不工作：verifier 打回来的 range 重灌时会撞 `ON CONFLICT`，`DO NOTHING` 会让 `row_count` 永远停在 0，于是这个 range 每天凌晨被重灌一次、永远标不干净。

```rust
pub async fn write_range(
    tx: &mut Transaction<'_, Postgres>,
    from: u64,
    to: u64,
    logs: &[Log],
) -> Result<(), sqlx::Error> {
    // 这个 range 可能是 verifier 打回来重灌的。重灌前先清掉旧行，否则 COPY 会
    // 叠出重复 log。只在 ranges_done 里已经有这一行时才做，首灌路径不受影响。
    let is_refill: Option<(i64,)> = sqlx::query_as(
        "SELECT row_count FROM ranges_done WHERE from_block = $1"
    )
    .bind(from as i64)
    .fetch_optional(&mut **tx)
    .await?;

    if is_refill.is_some() {
        let deleted = sqlx::query("DELETE FROM logs WHERE block_number BETWEEN $1 AND $2")
            .bind(from as i64)
            .bind(to as i64)
            .execute(&mut **tx)
            .await?
            .rows_affected();
        info!(from, to, deleted, "refilling range");
    }

    if !logs.is_empty() {
        let mut copy = tx.copy_in_raw(
            "COPY logs (block_number, tx_index, log_index, address, topic0, topics, data) \
             FROM STDIN WITH (FORMAT csv)"
        ).await?;
        copy.send(encode_csv(logs).as_bytes()).await?;
        let copied = copy.finish().await?;

        // 不 panic：返回 Err 让整个事务回滚，range 不会被标 done，上层照常重试。
        // panic 只会打掉这个 worker，剩下 23 个继续跑，反而更难发现。
        if copied != logs.len() as u64 {
            error!(from, to, expected = logs.len(), copied, "COPY row count mismatch");
            metrics::counter!("copy_mismatch_total").increment(1);
            return Err(sqlx::Error::Protocol(format!(
                "COPY wrote {copied} rows for range {from}..={to}, expected {}",
                logs.len()
            )));
        }
    }

    sqlx::query(
        "INSERT INTO ranges_done (from_block, to_block, row_count, finished_at) \
         VALUES ($1, $2, $3, now()) \
         ON CONFLICT (from_block) DO UPDATE \
            SET to_block    = EXCLUDED.to_block, \
                row_count   = EXCLUDED.row_count, \
                finished_at = EXCLUDED.finished_at"
    )
    .bind(from as i64)
    .bind(to as i64)
    .bind(logs.len() as i64)
    .execute(&mut **tx)
    .await?;

    info!(from, to, rows = logs.len(), "range done");
    Ok(())
}
```

三点说明：

- **你说的 panic 我改成了返回 `Err`**。意图一样（不许静默标 done），但 `Err` 会回滚事务、range 保持未完成状态、上层正常重试；panic 在 tokio task 里只是悄悄干掉一个 worker。想要原版的话把那个 `return Err(...)` 换成 `panic!` 即可。
- **`DELETE` 那段依赖 `logs` 上有 `block_number` 打头的索引**（主键是 `(block_number, tx_index, log_index)` 的话就有）。如果没有，12 亿行上的顺序扫描会把库打死 —— 这种情况下先别合这段，改用别的去重方式。
- `sqlx::Error::Protocol(String)` 是 0.7/0.8 的签名，老版本可能要调。

### 4. `src/verify.rs` —— 你要的第 2 条

顺便把 `.unwrap()` 去掉（这个 panic 会让整个凌晨任务挂掉且不留痕），签名变成 `Result`，调用方要跟着改一行。

```rust
pub async fn verify(pool: &PgPool, start: u64, head: u64) -> Result<Vec<(u64, u64)>, sqlx::Error> {
    let rows = sqlx::query_as::<_, (i64, i64, i64)>(
        "SELECT from_block, to_block, row_count FROM ranges_done ORDER BY from_block"
    )
    .fetch_all(pool)
    .await?;

    let mut gaps = Vec::new();
    let mut zero_ranges = 0u64;
    let mut cursor = start;

    for (f, t, row_count) in rows {
        let (f, t) = (f as u64, t as u64);

        if f > cursor {
            gaps.push((cursor, f - 1));
        }

        // 标了 done 却一行都没有的 range 也算洞。Base 上 128 个区块
        // （约 4 分钟）平均 ~10k 条 log，真正的空 range 不存在。
        if row_count == 0 && t >= start && f <= head {
            zero_ranges += 1;
            gaps.push((f.max(start), t.min(head)));
        }

        cursor = cursor.max(t + 1);
    }

    if cursor <= head {
        gaps.push((cursor, head));
    }

    metrics::gauge!("verify_zero_row_ranges").set(zero_ranges as f64);
    Ok(merge_ranges(gaps))
}

/// 排序后合并相邻/重叠区间，避免同一段被重灌两次
fn merge_ranges(mut gaps: Vec<(u64, u64)>) -> Vec<(u64, u64)> {
    gaps.sort_unstable();
    let mut out: Vec<(u64, u64)> = Vec::with_capacity(gaps.len());
    for (f, t) in gaps {
        match out.last_mut() {
            Some(last) if f <= last.1.saturating_add(1) => last.1 = last.1.max(t),
            _ => out.push((f, t)),
        }
    }
    out
}
```

`verify_zero_row_ranges` 这个 gauge 值得上告警：修完 fetch 之后它应该恒为 0，再冒头就说明又出现了新的静默转空路径。

